internal static class ThreadCopyTests
{
    private static void Assert(bool ok,string message){if(!ok)throw new Exception(message);}
    private static void Refused(Action action){try{action();}catch(InvalidOperationException){return;}throw new Exception("Expected refusal");}
    private static byte[] FixturePng()
    {
        // A valid 300x200 RGBA PNG with stored (uncompressed) DEFLATE blocks.
        // System.Drawing independently decodes it in the assertions below.
        var raw=new byte[200*(1+300*4)];for(int y=0;y<200;y++)for(int x=0;x<300;x++){int offset=y*(1+300*4)+1+x*4;raw[offset+1]=200;raw[offset+3]=255;}
        uint a=1,b=0;foreach(byte value in raw){a=(a+value)%65521;b=(b+a)%65521;}
        byte[] zlib;using(var zip=new MemoryStream()){zip.WriteByte(0x78);zip.WriteByte(1);for(int p=0;p<raw.Length;){int n=Math.Min(65535,raw.Length-p);zip.WriteByte((byte)(p+n==raw.Length?1:0));zip.WriteByte((byte)n);zip.WriteByte((byte)(n>>8));zip.WriteByte((byte)~n);zip.WriteByte((byte)(~n>>8));zip.Write(raw,p,n);p+=n;}uint adler=(b<<16)|a;for(int shift=24;shift>=0;shift-=8)zip.WriteByte((byte)(adler>>shift));zlib=zip.ToArray();}
        using(var png=new MemoryStream()){
            png.Write(new byte[]{137,80,78,71,13,10,26,10},0,8);
            Action<string,byte[]> chunk=(type,data)=>{uint n=(uint)data.Length;for(int shift=24;shift>=0;shift-=8)png.WriteByte((byte)(n>>shift));byte[] body=System.Text.Encoding.ASCII.GetBytes(type).Concat(data).ToArray();png.Write(body,0,body.Length);uint crc=0xffffffff;foreach(byte value in body){crc^=value;for(int bit=0;bit<8;bit++)crc=(crc>>1)^((crc&1)==0?0:0xedb88320);}crc^=0xffffffff;for(int shift=24;shift>=0;shift-=8)png.WriteByte((byte)(crc>>shift));};
            chunk("IHDR",new byte[]{0,0,1,44,0,0,0,200,8,6,0,0,0});chunk("tEXt",System.Text.Encoding.UTF8.GetBytes("Author\0Fixture metadata"));chunk("IDAT",zlib);chunk("IEND",new byte[0]);return png.ToArray();
        }
    }
    private sealed class Fixture
    {
        internal AccountService Accounts;internal RelayStore Store;internal DesktopInstance Source,Target;
        internal string SourceId=Guid.NewGuid().ToString(),TargetId,PathSource,PathTarget,HomeSource,HomeTarget,Folder;
        internal string Job=Guid.NewGuid().ToString("N");internal int Forks,Mutations,IdleChecks;
        internal bool Busy,Uncertain,Mismatch,Changed,Missing,MigrationFails,VisibleMissing,EmptyVisible;internal int Migrations;
        internal object ForkArgs;internal ThreadCopies Copies;
        internal string LocalImage,EmbeddedImage;internal bool DropTargetImage;
        internal bool NativeAbort,UnlabelledAbort;
        internal long? AvailableBytes=100*StorageBudget.GiB;
        internal bool RefuseTargetSpace;
        internal readonly List<string> BudgetDestinations=new List<string>();
        internal Fixture(string root,string auth,string other)
        {
            Accounts=new AccountService(Path.Combine(root,"copy-"+Guid.NewGuid().ToString("N")));Store=new RelayStore(Path.Combine(Accounts.Vault.Root,"relay"));
            Source=Accounts.Instances.Create("Source");Accounts.Instances.BindAccount(Source,Accounts.Import(auth,"Source"));Target=Accounts.Instances.Create("Destination");Accounts.Instances.BindAccount(Target,Accounts.Import(other,"Destination"));
            HomeSource=Accounts.Instances.Home(Source);HomeTarget=Accounts.Instances.Home(Target);Folder=Path.Combine(Accounts.Vault.Root,"project");Directory.CreateDirectory(Folder);
            Directory.CreateDirectory(Path.Combine(HomeSource,"sessions"));Directory.CreateDirectory(Path.Combine(HomeTarget,"sessions"));PathSource=Path.Combine(HomeSource,"sessions","source.jsonl");History("paginated");
            Copies=new ThreadCopies(Store,home=>new Rpc(this,home==HomeSource),async(a,i,w,t,c)=>{IdleChecks++;if(Busy)throw new InvalidOperationException("busy");if(Changed&&IdleChecks==2)File.AppendAllText(PathSource,Line("response_item",new{type="message",role="user",content=new[]{new{type="input_text",text="changed"}}}));await Task.FromResult(0);},async(e,h,t,c)=>{Assert(h==HomeTarget&&t==TargetId,"migration scope mismatch");Migrations++;if(MigrationFails)throw new InvalidOperationException("migration unavailable");await Task.FromResult(0);},Capacity);
        }
        internal StorageBudgetVolume Capacity(string path){BudgetDestinations.Add(path);return new StorageBudgetVolume{Root=Path.GetPathRoot(path),AvailableBytes=RefuseTargetSpace&&RelayStore.SamePath(path,HomeTarget)?0:AvailableBytes};}
        internal static string Line(string type,object payload){return Json.Write(new{type=type,payload=payload})+"\n";}
        internal void History(string mode){File.WriteAllText(PathSource,Line("session_meta",new{id=SourceId,history_mode=mode,cwd=Folder})+Line("response_item",new{type="message",role="user",content=new[]{new{type="input_text",text="remember ORANGE-42"}}})+Line("event_msg",new{type="user_message",message="remember ORANGE-42"})+Line("response_item",new{type="message",role="assistant",content=new[]{new{type="output_text",text="Remembered."}},phase="final_answer"}));}
        internal ThreadCopyRecord Copy(){return Copies.Copy(Job,Source.Id,Target.Id,SourceId,"My copy",CancellationToken.None).GetAwaiter().GetResult();}
        internal object Thread(bool source){return new{id=source?SourceId:TargetId,path=source?PathSource:PathTarget,cwd=Folder,name=source?"Original":"Copy",historyMode=source?"paginated":"legacy"};}
        private sealed class Rpc:IThreadProfileRpc
        {
            private readonly Fixture f;private readonly bool source;
            internal Rpc(Fixture f,bool source){this.f=f;this.source=source;}
            public void Dispose(){}
            public Task<object> Call(string method,object parameters,CancellationToken token)
            {
                object value=null;parameters=Json.Read<object>(Json.Write(parameters));
                if(method=="thread/read")value=new{thread=f.Thread(source)};
                else if(method=="thread/list"){Assert(Equals(Json.Get(parameters,"useStateDbOnly"),true),"indexed desktop threads omitted");value=new{data=f.Missing?new object[0]:new[]{f.Thread(source)},nextCursor=(string)null};}
                else if(method=="thread/start"||method=="thread/resume"){if(method=="thread/resume"&&f.NativeAbort&&!source){File.AppendAllText(f.PathTarget,Line("response_item",new{type="message",role="developer",content=new[]{new{type="input_text",text=RolloutSnapshot.NativeAbortText}},internal_chat_message_metadata_passthrough=new{content_item_kinds=new[]{f.UnlabelledAbort?"other":"generic.turn_aborted"}}})+Line("event_msg",new{type="turn_aborted"})+Line("event_msg",new{type="thread_settings_applied"}));}value=new{thread=new{id=Guid.NewGuid().ToString()},activePermissionProfile=new{id=":read-only"},approvalPolicy="on-request",approvalsReviewer="user"};}
                else if(method=="thread/unsubscribe")value=new{};
                else if(method=="thread/items/list"){Assert(Convert.ToInt32(Json.Get(parameters,"limit"))==10,"image-heavy pages are not bounded");var content=new List<object>{new{type="text",text="remember ORANGE-42"}};if(f.LocalImage!=null&&(source||!f.DropTargetImage))content.Add(new{type="localImage",path=f.LocalImage,detail=(string)null});if(f.EmbeddedImage!=null&&(source||!f.DropTargetImage))content.Add(new{type="image",url=f.EmbeddedImage,detail=(string)null});value=new{data=f.EmptyVisible||(f.VisibleMissing&&!source)?new object[0]:new object[]{new{item=new{type="userMessage",content=content.ToArray()}}},nextCursor=(string)null};}
                else if(method=="thread/fork"){
                    f.ForkArgs=parameters;f.Forks++;f.TargetId=Guid.NewGuid().ToString();f.PathTarget=Path.Combine(f.HomeTarget,"sessions",f.TargetId+".jsonl");
                    var lines=File.ReadAllLines(Json.Str(Json.Get(parameters,"path")));var meta=Json.Read<object>(lines[0]);var payload=Json.Obj(Json.Get(meta,"payload"));payload["id"]=f.TargetId;payload["thread_source"]=Json.Get(parameters,"threadSource");lines[0]=Json.Write(meta);
                    File.WriteAllLines(f.PathTarget,lines);if(f.Mismatch)File.AppendAllText(f.PathTarget,Line("response_item",new{type="message",role="user",content=new[]{new{type="input_text",text="unexpected"}}}));
                    if(f.Uncertain)throw new IOException("response lost");value=new{thread=f.Thread(false)};
                }else if(method=="thread/name/set"||method=="thread/goal/clear"){f.Mutations++;value=new{};}
                else throw new Exception("Unexpected method "+method);
                return Task.FromResult(Json.Read<object>(Json.Write(value)));
            }
        }
    }
    internal static void RunAll(Action<string,Action> check,string root,string auth,string other)
    {
        check("thread copy refuses insufficient snapshot or target capacity before fork and preserves its original",delegate{
            foreach(bool target in new[]{false,true}){var f=new Fixture(root,auth,other){AvailableBytes=target?100*StorageBudget.GiB:0,RefuseTargetSpace=target};string before=RolloutSnapshot.Scan(f.PathSource,f.SourceId).Digest;StorageBudgetException refusal=null;try{f.Copy();}catch(StorageBudgetException error){refusal=error;}
                string scratch=Path.Combine(f.Store.Root,"thread-copies");Assert(refusal!=null&&f.Forks==0&&f.Mutations==0&&f.Migrations==0&&RolloutSnapshot.Scan(f.PathSource,f.SourceId).Digest==before&&(!Directory.Exists(scratch)||!Directory.GetFiles(scratch).Any()),"budget refusal forked, changed source or wrote an import snapshot");
                Assert(!target||f.BudgetDestinations.Any(path=>RelayStore.SamePath(path,f.HomeTarget)),"destination capacity was never checked");}
        });
        check("thread copy rebuilds a partial paginated display without changing model context",delegate{var f=new Fixture(root,auth,other);File.WriteAllText(f.PathSource,File.ReadAllText(f.PathSource).Replace("\"type\":\"user_message\",\"message\":\"remember ORANGE-42\"","\"type\":\"user_message\",\"message\":\"stale legacy display\""));string original=RolloutSnapshot.Scan(f.PathSource,f.SourceId).Digest,model=RolloutSnapshot.Scan(f.PathSource,f.SourceId).ModelDigest;Assert(f.Copy().State=="completed","partial transcript not repaired");Assert(RolloutSnapshot.Scan(f.PathTarget,f.TargetId).ModelDigest==model&&RolloutSnapshot.Scan(f.PathSource,f.SourceId).Digest==original,"model or source changed during display reconstruction");Assert(!File.Exists(f.PathTarget+".display-tmp"),"display scratch retained");});
        check("thread display reconstruction preserves an existing foreign scratch file",delegate{var f=new Fixture(root,auth,other);File.WriteAllText(f.PathSource,File.ReadAllText(f.PathSource).Replace("\"type\":\"user_message\",\"message\":\"remember ORANGE-42\"","\"type\":\"user_message\",\"message\":\"stale legacy display\""));string folder=Path.Combine(f.Store.Root,"thread-copies");Directory.CreateDirectory(folder);string foreign=Path.Combine(folder,f.Job+".jsonl.display-tmp");File.WriteAllText(foreign,"foreign scratch");try{f.Copy();throw new Exception("Expected scratch collision");}catch(IOException){}Assert(f.Forks==0&&File.ReadAllText(foreign)=="foreign scratch","foreign scratch overwritten or removed");});
        check("thread display reconstruction can preserve an empty native transcript",delegate{var f=new Fixture(root,auth,other){EmptyVisible=true};string model=RolloutSnapshot.Scan(f.PathSource,f.SourceId).ModelDigest;Assert(f.Copy().State=="completed"&&RolloutSnapshot.Scan(f.PathTarget,f.TargetId).VisibleMessages.Length==0&&RolloutSnapshot.Scan(f.PathTarget,f.TargetId).ModelDigest==model,"old display leaked into empty native transcript");});
        check("thread copy adapts obsolete annotations only for exact preserved tool calls",delegate{var f=new Fixture(root,auth,other);var arguments=new{name="été",count=1};File.AppendAllText(f.PathSource,Fixture.Line("response_item",new{type="function_call",name="js",@namespace="mcp__cua_repl",arguments=Json.Write(arguments),call_id="keep-this-id"})+Fixture.Line("response_item",new{type="function_call_output",call_id="keep-this-id",output="Done",internal_chat_message_metadata_passthrough=new{executed_tool_calls=new[]{new{name="mcp__cua_repl__js",arguments=arguments}},tool_calls_complete=true,content_item_kinds=new[]{"keep-this-kind"}}})+Fixture.Line("compacted",new{retained_context=new{user_messages=new object[0]},replacement_history=new object[0]}));string original=RolloutSnapshot.Scan(f.PathSource,f.SourceId).Digest;var copy=f.Copy();Assert(copy.State=="completed"&&copy.DuplicateToolAnnotations==1&&copy.EmptyContextDefaults==2,"native annotation adaptation not recorded");string target=File.ReadAllText(f.PathTarget);Assert(target.Contains("keep-this-id")&&target.Contains("keep-this-kind")&&!target.Contains("executed_tool_calls")&&target.Contains("assistant_messages_incomplete"),"tool call or metadata lost");Assert(RolloutSnapshot.Scan(f.PathSource,f.SourceId).Digest==original,"source annotations mutated");});
        check("thread copy refuses legacy annotation without an identical real call",delegate{var f=new Fixture(root,auth,other);File.AppendAllText(f.PathSource,Fixture.Line("response_item",new{type="function_call_output",call_id="missing-call",output="Historical output",internal_chat_message_metadata_passthrough=new{executed_tool_calls=new[]{new{name="missing_tool",arguments=new{important="value"}}},tool_calls_complete=true}}));Refused(()=>f.Copy());Assert(f.Forks==0,"unrepresented annotation silently discarded");});
        check("thread copy cannot map an old annotation to a different call identifier",delegate{var f=new Fixture(root,auth,other);var args=new{message="Important"};File.AppendAllText(f.PathSource,Fixture.Line("response_item",new{type="function_call",name="tool",arguments=Json.Write(args),call_id="actual-id"})+Fixture.Line("response_item",new{type="function_call_output",call_id="another-id",output="Historical output",internal_chat_message_metadata_passthrough=new{executed_tool_calls=new[]{new{name="tool",arguments=args}},tool_calls_complete=true}}));Refused(()=>f.Copy());Assert(f.Forks==0,"unrelated call accepted");});
        check("thread copy refuses incomplete annotations and preserves populated context",delegate{var f=new Fixture(root,auth,other);File.AppendAllText(f.PathSource,Fixture.Line("response_item",new{type="function_call_output",call_id="missing-call",output="Historical output",internal_chat_message_metadata_passthrough=new{executed_tool_calls=new object[0],tool_calls_complete=false}}));Refused(()=>f.Copy());Assert(f.Forks==0,"incomplete tool state discarded");var separate=new Fixture(root,auth,other);File.AppendAllText(separate.PathSource,Fixture.Line("compacted",new{retained_context=new{assistant_messages=new[]{"Important retained answer"},assistant_messages_incomplete=true}}));Assert(separate.Copy().State=="completed"&&File.ReadAllText(separate.PathTarget).Contains("Important retained answer"),"retained assistant content changed");});
        check("thread copy converts journal and native inline image field names identically",delegate{string url="data:image/png;base64,"+Convert.ToBase64String(FixturePng());string previous=null;foreach(string field in new[]{"url","image_url"}){var content=new System.Collections.Generic.Dictionary<string,object>{{"type","image"},{field,url}};var display=RolloutSnapshot.LegacyDisplay(new System.Collections.Generic.Dictionary<string,object>{{"type","UserMessage"},{"content",new[]{content}}});string current=Json.Write(display);Assert(previous==null||current==previous,"journal image URL lost");previous=current;}Assert(!RolloutSnapshot.EmbeddedImage(Json.Read<object>("{\"type\":\"image\",\"url\":\"data:image/png;base64,AQ==\",\"image_url\":\"data:image/png;base64,Ag==\"}")),"conflicting image URLs accepted");});
        check("thread copy preserves embedded image bytes in modern display",delegate{string url="data:image/png;base64,"+Convert.ToBase64String(FixturePng());var display=RolloutSnapshot.LegacyDisplay(Json.Read<object>(Json.Write(new{type="UserMessage",content=new[]{new{type="image",url=url,detail=(string)null}}})));Assert(RelayEngine.Rows(Json.Get(Json.Read<object>(Json.Write(display)),"images")).Select(Json.Str).Single()==url,"embedded image bytes changed");Assert(RolloutSnapshot.VisibleDigest("user","",null,new[]{url})!=RolloutSnapshot.VisibleDigest("user","",null),"embedded image omitted from verification");});
        check("thread copy verifies embedded images after migration",delegate{var f=new Fixture(root,auth,other){EmbeddedImage="data:image/png;base64,"+Convert.ToBase64String(FixturePng())};string text=File.ReadAllText(f.PathSource).Replace("\"type\":\"user_message\"","\"type\":\"user_message\",\"images\":[\""+f.EmbeddedImage+"\"]");File.WriteAllText(f.PathSource,text);Assert(f.Copy().State=="completed","embedded image copy failed");});
        check("thread copy refuses a target missing an embedded image",delegate{var f=new Fixture(root,auth,other){EmbeddedImage="data:image/png;base64,"+Convert.ToBase64String(FixturePng()),DropTargetImage=true};File.WriteAllText(f.PathSource,File.ReadAllText(f.PathSource).Replace("\"type\":\"user_message\"","\"type\":\"user_message\",\"images\":[\""+f.EmbeddedImage+"\"]"));Refused(()=>f.Copy());Assert(f.Forks==1,"missing inline image not detected on destination");});
        check("thread copy refuses invalid inline data and unsupported image details",delegate{Refused(()=>RolloutSnapshot.VisibleDigest("user","",null,new[]{"data:image/png;base64,not-base64"}));Refused(()=>RolloutSnapshot.LegacyDisplay(Json.Read<object>(Json.Write(new{type="UserMessage",content=new[]{new{type="image",url="data:image/png;base64,AQ==",detail="high"}}}))));});
        check("history PNG encoding preserves raster and metadata with an independent decoder",delegate{byte[] original=FixturePng(),before=(byte[])original.Clone(),packed=PngHistoryEncoding.Repack(original);Assert(original.SequenceEqual(before)&&packed.Length<original.Length/10,"source changed or PNG not compacted");using(var a=new MemoryStream(original))using(var b=new MemoryStream(packed))using(var first=new System.Drawing.Bitmap(a))using(var second=new System.Drawing.Bitmap(b)){Assert(first.Size==second.Size,"dimensions changed");for(int y=0;y<200;y+=17)for(int x=0;x<300;x+=19)Assert(first.GetPixel(x,y)==second.GetPixel(x,y),"pixel changed");}Assert(System.Text.Encoding.UTF8.GetString(packed).Contains("Author\0Fixture metadata"),"metadata changed");});
        check("history PNG encoding refuses corrupt image checksums",delegate{var png=FixturePng();png[png.Length-1]^=1;Refused(()=>PngHistoryEncoding.Repack(png));});
        check("thread copy refuses oversized non-PNG history before creating a destination",delegate{var f=new Fixture(root,auth,other);File.AppendAllText(f.PathSource,"{\"type\":\"response_item\",\"payload\":{\"type\":\"message\",\"role\":\"user\",\"content\":[{\"type\":\"input_text\",\"text\":\""+new string('A',17*1024*1024)+"\"}]}}\n");string before=RolloutSnapshot.Scan(f.PathSource,f.SourceId).Digest,scratch=Path.Combine(f.Store.Root,"thread-copies");Refused(()=>f.Copy());Assert(f.Forks==0&&RolloutSnapshot.Scan(f.PathSource,f.SourceId).Digest==before&&(!Directory.Exists(scratch)||!Directory.GetFiles(scratch).Any()),"unsupported history copied or changed");});
        check("thread copy losslessly reduces oversized PNG history before native import",delegate{var f=new Fixture(root,auth,other);string image="data:image/png;base64,"+Convert.ToBase64String(FixturePng());string row=Json.Write(new{type="input_image",image_url=image});File.AppendAllText(f.PathSource,"{\"type\":\"response_item\",\"payload\":{\"type\":\"message\",\"role\":\"user\",\"content\":["+String.Join(",",Enumerable.Repeat(row,60))+"]}}\n");string original=RolloutSnapshot.Scan(f.PathSource,f.SourceId).Digest;var r=f.Copy();Assert(r.State=="completed"&&r.LosslessPngEncoding&&new FileInfo(f.PathTarget).Length<new FileInfo(f.PathSource).Length/10,"large PNG history not imported");Assert(RolloutSnapshot.Scan(f.PathSource,f.SourceId).Digest==original,"original history rewritten");});
        check("thread copy accepts only the tagged native notice for an interrupted turn",delegate{var f=new Fixture(root,auth,other){NativeAbort=true};var copy=f.Copy();Assert(copy.State=="completed"&&copy.NativeResumeNotice&&copy.ModelItems==3,"native abort notice not verified");});
        check("thread copy does not normalize an arbitrary developer message",delegate{var f=new Fixture(root,auth,other){NativeAbort=true,UnlabelledAbort=true};Assert(f.Copy().State=="verification_failed","unlabelled context accepted");int mutations=f.Mutations;Assert(f.Copy().State=="verification_failed"&&f.Forks==1&&f.Mutations==mutations,"mismatch retry mutated copy");});
