        check("thread copy retains earlier native notices when more model context follows",delegate{var f=new Fixture(root,auth,other);File.AppendAllText(f.PathSource,Fixture.Line("response_item",new{type="message",role="developer",content=new[]{new{type="input_text",text=RolloutSnapshot.NativeAbortText}},internal_chat_message_metadata_passthrough=new{content_item_kinds=new[]{"generic.turn_aborted"}}})+Fixture.Line("event_msg",new{type="turn_aborted"})+Fixture.Line("response_item",new{type="message",role="user",content=new[]{new{type="input_text",text="new turn"}}}));var normal=RolloutSnapshot.Scan(f.PathSource,f.SourceId);var strict=RolloutSnapshot.Scan(f.PathSource,f.SourceId,null,CancellationToken.None,true);Assert(!strict.NativeResumeNotice&&strict.ModelItems==normal.ModelItems&&strict.Digest==normal.Digest,"earlier native model context lost");});
