        check("thread copy refuses a native destination that drops an image",delegate{var f=new Fixture(root,auth,other){DropTargetImage=true};f.LocalImage=Path.Combine(f.Folder,"attachment.png");File.WriteAllBytes(f.LocalImage,new byte[]{1});File.WriteAllLines(f.PathSource,File.ReadAllLines(f.PathSource).Where(l=>!l.Contains("\"type\":\"event_msg\"")));Refused(()=>f.Copy());Assert(f.Forks==1&&f.Copies.Recent(f.Source.Id).Single().State=="migrating","image loss marked completed");f.DropTargetImage=false;Assert(f.Copy().State=="completed"&&f.Forks==1,"image verification retry duplicated history");});
        check("thread copy refuses missing SQLite image before destination mutation",delegate{var f=new Fixture(root,auth,other);f.LocalImage=Path.Combine(f.Folder,"missing.png");File.WriteAllLines(f.PathSource,File.ReadAllLines(f.PathSource).Where(l=>!l.Contains("\"type\":\"event_msg\"")));Refused(()=>f.Copy());Assert(f.Forks==0,"missing image imported");});
        check("thread copy converts modern local image display without empty text blocks",delegate{var f=new Fixture(root,auth,other);string image=Path.Combine(f.Folder,"image.png");File.WriteAllBytes(image,new byte[]{1});foreach(string kind in new[]{"localImage","local_image"}){var display=Json.Read<object>(Json.Write(RolloutSnapshot.LegacyDisplay(Json.Read<object>(Json.Write(new{type="UserMessage",content=new object[]{new{type="text",text="hello"},new{type=kind,path=image}}})))));Assert(Json.Str(Json.Get(display,"message"))=="hello"&&RelayEngine.Rows(Json.Get(display,"local_images")).Select(Json.Str).Single()==image,"modern image lost or text changed");}});
        check("thread copy reads large image items without loosening general JSON limits",delegate{var f=new Fixture(root,auth,other);string item="{\"type\":\"response_item\",\"payload\":{\"type\":\"message\",\"role\":\"user\",\"content\":[{\"type\":\"input_image\",\"image_url\":\"data:image/png;base64,"+new string('A',5*1024*1024)+"\"}]}}";bool refused=false;try{Json.Read<object>(item);}catch(ArgumentException){refused=true;}catch(InvalidOperationException){refused=true;}Assert(refused,"general JSON limit increased");File.AppendAllText(f.PathSource,item+"\n");string path=Path.Combine(f.Folder,"large-snapshot.jsonl");var before=RolloutSnapshot.ScanWithBudget(f.PathSource,f.SourceId,path,CancellationToken.None,false,f.Capacity);Assert(RolloutSnapshot.Scan(path,f.SourceId).ModelDigest==before.ModelDigest,"large payload changed");File.Delete(path);});
