        check("thread copy converts modern display messages without altering model context",delegate{var f=new Fixture(root,auth,other);string before=RolloutSnapshot.Scan(f.PathSource,f.SourceId).ModelDigest;File.AppendAllText(f.PathSource,Fixture.Line("event_msg",new{type="item_completed",thread_id=f.SourceId,turn_id="turn",item=new{type="AgentMessage",content=new[]{new{type="Text",text="Visible modern answer"}},phase="final_answer"}}));string snapshot=Path.Combine(f.Folder,"snapshot.jsonl");RolloutSnapshot.ScanWithBudget(f.PathSource,f.SourceId,snapshot,CancellationToken.None,false,f.Capacity);var after=RolloutSnapshot.Scan(snapshot,f.SourceId);Assert(after.ModelDigest==before&&after.VisibleMessages.Contains(RolloutSnapshot.TextDigest("assistant","Visible modern answer")),"modern UI lost or model changed");});
        check("thread copy refuses unknown multimodal display instead of silently dropping it",delegate{Refused(()=>RolloutSnapshot.LegacyDisplay(Json.Read<object>("{\"type\":\"UserMessage\",\"content\":[{\"type\":\"image\",\"url\":\"https://example.invalid/a.png\"}]}")));var converted=RolloutSnapshot.LegacyDisplay(Json.Read<object>("{\"type\":\"UserMessage\",\"content\":[{\"type\":\"text\",\"text\":\"hello\"}]}"));Assert(Json.Write(converted).Contains("hello"),"text not converted");});
        check("thread copy migration failure preserves one copy and retries verification",delegate{var f=new Fixture(root,auth,other){MigrationFails=true};Refused(()=>f.Copy());Assert(f.Forks==1&&f.Copies.Recent(f.Source.Id).Single().State=="migrating","failed conversion reported success");int mutations=f.Mutations;f.MigrationFails=false;Assert(f.Copy().State=="completed"&&f.Forks==1&&f.Migrations==2&&f.Mutations==mutations,"retry duplicated or mutated copy");});
        check("thread copy migrating retry rechecks capacity before conversion without reforking or modifying either history",delegate{var f=new Fixture(root,auth,other){MigrationFails=true};Refused(()=>f.Copy());Assert(f.Forks==1&&f.Migrations==1,"fixture did not reach the recoverable migration stage");string original=RolloutSnapshot.Scan(f.PathSource,f.SourceId).Digest,target=RolloutSnapshot.Scan(f.PathTarget,f.TargetId).Digest;int mutations=f.Mutations;f.MigrationFails=false;f.AvailableBytes=0;bool refused=false;try{f.Copy();}catch(StorageBudgetException){refused=true;}Assert(refused&&f.Forks==1&&f.Migrations==1&&f.Mutations==mutations&&f.Copies.Recent(f.Source.Id).Single().State=="migrating"&&RolloutSnapshot.Scan(f.PathSource,f.SourceId).Digest==original&&RolloutSnapshot.Scan(f.PathTarget,f.TargetId).Digest==target,"low-space retry converted, reforked or changed history");});
        check("thread copy migration requires exact target and a successful native outcome",delegate{string id=Guid.NewGuid().ToString();foreach(string status in new[]{"migrated","already_paginated"})ThreadCopyMigration.Validate(Json.Read<object>(Json.Write(new{outcomes=new[]{new{thread_id=id,status=status}}})),id);foreach(string status in new[]{"eligible","skipped_busy","skipped_empty","missing_sqlite_metadata"})Refused(()=>ThreadCopyMigration.Validate(Json.Read<object>(Json.Write(new{outcomes=new[]{new{thread_id=id,status=status}}})),id));Refused(()=>ThreadCopyMigration.Validate(Json.Read<object>(Json.Write(new{outcomes=new[]{new{thread_id=Guid.NewGuid().ToString(),status="migrated"}}})),id));});
        check("desktop IPC discovery accepts only both exact native local app-tool pipe names",delegate{
            foreach(string prefix in new[]{"codex-browser-use-","codex-app-tools-"}){
                string native=@"\\.\pipe\"+prefix+"12345678-abcd-1234-abcd-123456789012";
                Assert(NamedInstances.AppPipeName(native),"native pipe excluded");
                foreach(string p in new[]{native+"junk",native+"\n",native+@"\child",native.Replace(@"\\.\",@"\\other\"),native.Replace(prefix,prefix+"junk-"),native.Replace(prefix,"other-app-tools-"),native.Replace("12345678-abcd-1234-abcd-123456789012","12345678abcd-1234-abcd-123456789012"),native.Replace(prefix,prefix.ToUpperInvariant())})Assert(!NamedInstances.AppPipeName(p),"foreign pipe accepted");
            }
            foreach(string p in new[]{@"\\.\pipe\codex-browser-use\12345678-abcd-1234-abcd-123456789012",@"\\.\pipe\codex-ipc",@"\\.\pipe\codex-browser-use-not-a-guid",@"\\.\pipe\codex-app-tools-not-a-guid"})Assert(!NamedInstances.AppPipeName(p),"foreign pipe accepted");
        });
        check("desktop host observes both native app-tool prefixes without accepting partial or unrelated log names",delegate{
            foreach(string prefix in new[]{"codex-browser-use-","codex-app-tools-"}){
                string name=prefix+"12345678-abcd-1234-abcd-123456789012",pipe=@"\\.\pipe\"+name;
                Assert(InstanceHost.AppPipeFromLog("dynamic_app_tools_listening name="+name)==pipe&&InstanceHost.AppPipeFromLog("dynamic_app_tools_listening pipe=\""+pipe+"\"")==pipe,"host ignored native pipe");
                foreach(string text in new[]{"unrelated_event "+name,"dynamic_app_tools_listening "+name+"junk","dynamic_app_tools_listening foreign-"+name,"dynamic_app_tools_listening "+name+@"\child","dynamic_app_tools_listening "+prefix+"not-a-guid"})Assert(InstanceHost.AppPipeFromLog(text)==null,"host accepted unrelated or malformed pipe");
            }
        });
        check("managed desktop fallback requires its exact process identity before accepting a discovered endpoint",delegate{
            string wrong=@"\\.\pipe\codex-app-tools-11111111-2222-3333-4444-555555555555",right=@"\\.\pipe\codex-app-tools-12345678-abcd-1234-abcd-123456789012";
            var state=new InstanceState{Running=true,Phase="running",DesktopPid=222,DesktopStartTicks=333};int checks=0;
            string actual=NamedInstances.DiscoverPipe(state,new[]{@"\\.\pipe\unrelated",wrong,right},(path,pid,ticks)=>{checks++;Assert(pid==222&&ticks==333,"discovery lost expected managed identity");return path==right;},CancellationToken.None);
            Assert(actual==right&&checks==2,"fallback accepted another desktop or skipped the verified endpoint");
            foreach(string invalid in new[]{"closed","unknown","pid","ticks"}){
                var stale=new InstanceState{Running=invalid!="closed",Phase=invalid=="unknown"?"unknown":"running",DesktopPid=invalid=="pid"?0:222,DesktopStartTicks=invalid=="ticks"?0:333};int probes=0;
                Assert(NamedInstances.DiscoverPipe(stale,new[]{right},(path,pid,ticks)=>{probes++;return true;},CancellationToken.None)==null&&probes==0,"unverified runtime reached native discovery");
            }
            using(var cancel=new CancellationTokenSource()){cancel.Cancel();bool cancelled=false;try{NamedInstances.DiscoverPipe(state,new[]{right},(path,pid,ticks)=>{throw new Exception("cancelled discovery reached a pipe");},cancel.Token);}catch(OperationCanceledException){cancelled=true;}Assert(cancelled,"discovery ignored cancellation");}
        });
